css:
/* Atelier Martha — Galerie. Global layer: fonts, type scale (clamp chain), buttons,
   navigation, effects Velox classes cannot express (gradients on text, pseudo elements). */
@font-face{font-family:"Geist";font-style:normal;font-weight:100 900;font-display:swap;src:url(/wp-content/plugins/velox/assets/fonts/geist-latin-wght-normal.woff2) format("woff2-variations");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:"Geist";font-style:normal;font-weight:100 900;font-display:swap;src:url(/wp-content/plugins/velox/assets/fonts/geist-latin-ext-wght-normal.woff2) format("woff2-variations");unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
:root{--ag-ink:#0e0d0c;--ag-paper:#f7f5f0;--ag-soft:#eeeae2;--ag-muted:#67625b;--ag-acc:#2c3ee8;--ag-acc2:#8a5cf6}
html{scroll-behavior:smooth}
body{font-family:"Geist",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--ag-paper);color:var(--ag-ink);-webkit-font-smoothing:antialiased;letter-spacing:-.011em}
::selection{background:#c9cffd;color:#0e0d0c}
body h1,body h2,body h3,body h4,body h5,body h6,body p,body blockquote{margin:0}
body h1,body h2,body h3,body h4,body h5,body h6{color:inherit;font-weight:620;letter-spacing:-.045em;line-height:1.02}
body h1{font-size:clamp(3.25rem,1.6rem + 5.2vw,6.25rem)}
body h2{font-size:clamp(2.25rem,1.4rem + 3vw,3.25rem);line-height:1.05}
body h3{font-size:clamp(1.375rem,1.1rem + .8vw,2.25rem);letter-spacing:-.025em;line-height:1.2}
body h4{font-size:clamp(1.125rem,1rem + .5vw,1.375rem)}
body h5{font-size:clamp(1rem,.95rem + .3vw,1.125rem)}
body h6{font-size:1rem}
.ag-step h3,.ag-price h3{font-size:1.5rem}
a{color:inherit}
.ag-grad{background:linear-gradient(100deg,var(--ag-acc) 10%,var(--ag-acc2) 90%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.ag-dark .ag-grad,.ag-footer .ag-grad,.ag-band-cta .ag-grad{background-image:linear-gradient(100deg,#9aa6ff 10%,#c4a8ff 90%)}
.ag-dark .ag-label,.ag-band-cta .ag-label{color:#9aa6ff}
/* buttons: arrow turns, the button rises a touch */
.ag-btn:hover{transform:translateY(-2px)}
.ag-btn:hover .ag-btn-ic{transform:rotate(45deg)}
.ag-btn-primary:hover{background:var(--ag-acc);box-shadow:0 18px 36px -16px rgba(44,62,232,.7)}
.ag-btn-secondary:hover{border-color:rgba(14,13,12,.25)}
.ag-btn-light:hover{background:#e9e7ff}
.ag-btn:focus-visible,.ag-cart a:focus-visible,.ag-logo:focus-visible{outline:3px solid rgba(44,62,232,.5);outline-offset:3px}
.ag-btns-c{justify-content:center}
/* navigation: a pill grows under the link; the current page keeps it */
.ag-nav .vx-nav-list{gap:6px}
.ag-nav .vx-nav-item>a{position:relative;display:block;padding:9px 14px;border-radius:999px;text-decoration:none;color:var(--ag-ink);transition:color .25s ease}
.ag-nav .vx-nav-item>a::before{content:"";position:absolute;inset:0;border-radius:inherit;background:var(--ag-soft);transform:scale(.6);opacity:0;transition:transform .35s cubic-bezier(.2,.7,.2,1),opacity .25s ease;z-index:-1}
.ag-nav .vx-nav-item>a:hover::before,.ag-nav .vx-nav-item>a[aria-current="page"]::before,.ag-nav .vx-nav-item>a.is-current::before{transform:none;opacity:1}
.ag-nav .vx-nav-item>a[aria-current="page"]{font-weight:600}
.ag-nav .vx-burger{padding:10px 14px;border-radius:999px;background:var(--ag-soft)}
.vx-oc .vx-nav-item>a{text-decoration:none;font-size:1.25em;letter-spacing:-.03em}
.ag-cart .vxs-cartbtn{color:inherit}
#kopf.is-stuck .ag-navbar{box-shadow:0 18px 50px -24px rgba(14,13,12,.4);background:rgba(255,255,255,.86)}
#kopf .ag-navbar{transition:box-shadow .35s ease,background-color .35s ease}
/* hero: a quiet ultramarine light behind the art */
.ag-hero{background:radial-gradient(900px 600px at 82% 18%,rgba(44,62,232,.12),transparent 60%),radial-gradient(700px 500px at 0% 100%,rgba(138,92,246,.08),transparent 60%),var(--ag-paper)}
.ag-hero-art img,.ag-about-media img{width:100%;height:100%;object-fit:cover;display:block}
/* the photo moves inside its frame: give it room so no edge ever shows */
.ag-about-media .ag-img{top:-12%;bottom:-12%;height:auto}
.ag-art-a img{transform:scale(1.04)}
.ag-chip-t b{display:block;color:var(--ag-ink);font-size:14px;font-weight:600}
/* marquee */
.ag-band .vx-mq-item{font-size:clamp(26px,3.4vw,48px);font-weight:620;letter-spacing:-.04em;color:var(--ag-ink)}
.ag-band .vx-mq-sep{color:var(--ag-acc);font-size:22px}
/* works row */
.ag-work img{width:100%;height:100%;object-fit:contain;display:block;filter:drop-shadow(0 18px 22px rgba(14,13,12,.28));transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.ag-work:hover img{transform:translateY(-6px) scale(1.02)}
.ag-work-media{transition:background-color .4s ease}
.ag-work:hover .ag-work-media{background:#e6e1d6}
.ag-hs .vx-hs-pin{padding:0 24px;gap:28px}
.ag-hs .vx-hs-track{gap:28px}
.ag-hs.vx-hs-on .vx-hs-pin{align-items:flex-start;padding-top:max(110px,16vh)}
.ag-hs.vx-hs-on .vx-hs-pin{padding:0 max(24px,calc((100vw - 1240px)/2 + 24px))}
/* about */
.ag-stat .vx-counter-num,.ag-stat [class*="num"]{font-weight:650;letter-spacing:-.04em;color:var(--ag-ink)}
.ag-stat [class*="label"]{font-size:14px;color:var(--ag-muted)}
/* process */
.ag-steps .vx-stack-card{box-shadow:0 -20px 60px -30px rgba(0,0,0,.6)}
/* prices */
.ag-price-hl .ag-check-ic{color:#9aa6ff}
.ag-price-from{font-size:15px;font-weight:500;letter-spacing:0;opacity:.55}
.ag-price-hl::before{content:"Beliebt";position:absolute;top:22px;right:22px;padding:5px 11px;border-radius:999px;background:linear-gradient(100deg,var(--ag-acc),var(--ag-acc2));color:#fff;font-size:12px;font-weight:600;letter-spacing:.02em}
/* faq */
.ag-faq .vx-acc-item,.ag-faq details{border-bottom:1px solid rgba(14,13,12,.1)}
.ag-faq summary,.ag-faq .vx-acc-btn{font-size:1.15rem}
.ag-help{text-decoration:none;color:var(--ag-ink);font-size:14px;line-height:1.5;transition:border-color .25s ease,transform .25s ease}
.ag-help:hover{border-color:rgba(44,62,232,.35);transform:translateY(-2px)}
/* contact form */
.ag-form .velox-form{background:none;box-shadow:none;border:0;border-radius:0;padding:0}
.ag-form .velox-form-submit{width:100%;padding:16px 26px;border:0;border-radius:999px;background:var(--ag-ink);color:#fff;font-weight:600;font-size:15px;cursor:pointer;transition:background .25s ease,transform .2s ease}
.ag-form .velox-form-submit:hover{background:var(--ag-acc)}
.ag-form .velox-form :where(input,textarea,select){border-radius:14px;border:1px solid rgba(14,13,12,.12);background:var(--ag-paper);padding:13px 15px}
.ag-form .velox-form :where(input,textarea,select):focus{outline:0;border-color:var(--ag-acc);box-shadow:0 0 0 4px rgba(44,62,232,.14)}
.ag-contact-row{transition:color .2s ease}.ag-contact-row:hover{color:#c4a8ff}
/* footer */
.ag-footer a{text-decoration:none;color:#bdb8b0;transition:color .2s ease}.ag-footer a:hover{color:#fff}
.ag-footer a.ag-btn-light,.ag-footer a.ag-btn-light:hover{color:var(--ag-ink)}
.ag-footer p{line-height:1.7}
.ag-withdraw{display:inline-flex;align-self:flex-start;padding:9px 15px;border-radius:999px;border:1px solid rgba(255,255,255,.14);font-size:14px}
.ag-wordmark{-webkit-text-stroke:1px rgba(255,255,255,.2);user-select:none}
.ag-top{background:var(--ag-ink);color:#fff}
/* page templates */
.ag-pagehead{background:radial-gradient(800px 420px at 85% 0%,rgba(44,62,232,.12),transparent 60%),var(--ag-soft)}
.ag-content .velox-legacy-content{display:flex;flex-direction:column;gap:16px}
.ag-content .velox-legacy-content:not(:has(.vxs-cartpage,.vxs-checkout,.vxs-account,.vxs-order,.vxs-product,.vxs-grid)){max-width:780px}
.ag-content .velox-legacy-content>:where(h2,h3):not(:first-child){padding-top:18px}
.ag-content .velox-legacy-content>:where(p,ul,ol){color:var(--ag-muted);font-size:16.5px;line-height:1.75}
.ag-content h2{font-size:clamp(1.5rem,1.2rem + 1vw,2rem)}
.ag-content :where(ul,ol){margin:0;padding-left:20px}
.am-note{background:#fff;border:1px solid rgba(14,13,12,.08);border-left:3px solid var(--ag-acc);border-radius:12px;padding:14px 18px;font-size:14px!important;color:var(--ag-muted)}
/* shop in the house style */
.ag-shophead{background:radial-gradient(800px 420px at 85% 0%,rgba(44,62,232,.1),transparent 60%),var(--ag-paper)}
.ag-shopgrid{padding-top:20px}
.vxs-cats a[aria-current=true]{background:var(--ag-ink);border-color:var(--ag-ink)}
.vxs-btn{font-weight:600}
@media (max-width:991px){.ag-nav .vx-nav-list{gap:0}}
@media (max-width:480px){.ag-nav .vx-burger-l{display:none}.ag-nav .vx-burger{padding:11px}.ag-logo{font-size:16px}.ag-navbar{gap:8px!important}}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.ag-btn,.ag-btn-ic,.ag-work img{transition:none}}
